`timescale 1ns/1ps
// Driven by run_tests.py. The expected cycle-by-cycle trace is generated by
// an independent Python model anchored to published NESSIE known answers.
module tb_pipeline;
    parameter KEY_BITS = 256;
    parameter BLOCKS = 1;
    parameter USE_ECB = 0;
    parameter LATENCY = 32;
    localparam WIDTH = 128 * BLOCKS;
    reg clk = 0;
    always #5 clk = ~clk;
    reg rst = 0, key_load = 0, in_valid = 0;
    reg [KEY_BITS-1:0] key_in = 0;
    reg [WIDTH-1:0] data_in = 0;
    wire key_ready, in_ready, out_valid;
    wire [WIDTH-1:0] data_out;
    generate
        if (USE_ECB) begin : ecb
            SerpentEncryptECB #(.KEY_BITS(KEY_BITS), .BLOCKS(BLOCKS)) dut (
                .clk(clk), .rst(rst), .key_load(key_load), .key_in(key_in),
                .in_valid(in_valid), .data_in(data_in), .key_ready(key_ready),
                .in_ready(in_ready), .out_valid(out_valid), .data_out(data_out));
        end else begin : single
`ifdef TWO_ROUNDS
            SerpentEncryptTopPipelined2R #(.KEY_BITS(KEY_BITS)) dut (
`else
            SerpentEncryptTopPipelined #(.KEY_BITS(KEY_BITS)) dut (
`endif
                .clk(clk), .rst(rst), .key_load(key_load), .key_in(key_in),
                .in_valid(in_valid), .data_in(data_in), .key_ready(key_ready),
                .in_ready(in_ready), .out_valid(out_valid), .data_out(data_out));
        end
    endgenerate

    integer fd, scan, cycle = 0, outputs = 0;
    integer srst, sload, svalid, expected_in_ready, expected_key_ready;
    integer expected_out_valid;
    reg [WIDTH-1:0] expected_data;
    string vector_file;
    initial begin
        if (!$value$plusargs("vectors=%s", vector_file))
            $fatal(1, "Missing +vectors=<cycle trace file>");
        fd = $fopen(vector_file, "r");
        if (!fd) $fatal(1, "Cannot open cycle trace %s", vector_file);
        while (!$feof(fd)) begin
            @(negedge clk);
            scan = $fscanf(fd, "%d %d %d %h %h %d %d %d %h\n",
                srst, sload, svalid, key_in, data_in, expected_in_ready,
                expected_key_ready, expected_out_valid, expected_data);
            if (scan != 9) $fatal(1, "Malformed trace at cycle %0d (%0d fields)", cycle, scan);
            rst = srst; key_load = sload; in_valid = svalid;
            #1;
            if (in_ready !== (expected_in_ready != 0))
                $fatal(1, "in_ready cycle=%0d got=%b expected=%0d", cycle, in_ready, expected_in_ready);
            @(posedge clk);
            #1;
            if (key_ready !== (expected_key_ready != 0))
                $fatal(1, "key_ready cycle=%0d got=%b expected=%0d", cycle, key_ready, expected_key_ready);
            if (out_valid !== (expected_out_valid != 0))
                $fatal(1, "out_valid/latency cycle=%0d got=%b expected=%0d (latency %0d)", cycle, out_valid, expected_out_valid, LATENCY);
            if (data_out !== expected_data)
                $fatal(1, "data_out cycle=%0d valid=%b got=%h expected=%h", cycle, out_valid, data_out, expected_data);
            if (out_valid) outputs = outputs + 1;
            cycle = cycle + 1;
        end
        $fclose(fd);
        if (outputs < 50) $fatal(1, "Insufficient valid outputs: %0d", outputs);
        $display("PASS cycles=%0d outputs=%0d KEY_BITS=%0d BLOCKS=%0d ECB=%0d latency=%0d", cycle, outputs, KEY_BITS, BLOCKS, USE_ECB, LATENCY);
        $finish;
    end
    initial begin
        #10000000;
        $fatal(1, "Simulation timeout");
    end
endmodule
